const raw = $input.response;
const buckets = ['data','list','rows','result','items','records','body','payload'];
let arr = Array.isArray(raw) ? raw : null;
if (!arr && raw && typeof raw === 'object') {
  for (const k of buckets) { if (Array.isArray(raw[k])) { arr = raw[k]; break; } }
  if (!arr) { const v = Object.values(raw).find(x => Array.isArray(x)); if (v) arr = v; }
}
if (!arr) arr = (raw && typeof raw === 'object') ? [raw] : [];
