const planKeys = ['package','package_name','plan','plan_name','product_name','product','service_name','套餐','套餐名','套餐名称'];
function pick(obj, keys) {
  for (const k of Object.keys(obj)) {
    if (keys.includes(k) || keys.includes(k.toLowerCase())) return obj[k];
  }
  return undefined;
}
const map = {};
for (const it of arr) {
  if (!it || typeof it !== 'object') continue;
  let num = pick(it, numKeys);
  if (num === undefined) num = Object.values(it).find(v => typeof v === 'string' && /^\d{5,}$/.test(v.trim()));
  let plan = pick(it, planKeys);
  if (plan === undefined) {
    const strs = Object.values(it).filter(v => typeof v === 'string' && v !== String(num));
    plan = strs.length ? strs[strs.length - 1] : null;
  }
  if (num === undefined || num === null) continue;
  map[String(num).trim()] = plan == null ? null : String(plan).trim();
}
